const official2026SiberianHuskySchedules = [
  [1, "[2, 4, 5, 6, 9]", "[2, 5, 8, 12, 19]"],
  [2, "[2, 3, 4, 6, 10]", "[2, 4, 6, 10, 16]"],
  [3, "[2, 4, 6, 9, 14]", "[2, 5, 7, 10, 15]"],
  [4, "[2, 3, 4, 5, 7]", "[2, 4, 5, 7, 10]"],
  [5, "[2, 3, 4, 5, 7]", "[2, 4, 5, 7, 10]"],
  [6, "[2, 3, 4, 5, 6]", "[2, 4, 5, 7, 10]"],
  [7, "[2, 4, 5, 8, 13]", "[2, 4, 6, 10, 18]"],
  [8, "[2, 4, 5, 7, 11]", "[2, 3, 4, 8, 14]"],
  [9, "[2, 3, 4, 5, 6]", "[2, 4, 5, 7, 10]"],
  [10, "[2, 3, 4, 5, 6]", "[2, 3, 4, 5, 6]"],
  [11, "[2, 3, 4, 5, 6]", "[2, 3, 4, 5, 6]"],
  [12, "[2, 3, 4, 5, 6]", "[2, 3, 4, 5, 6]"],
  [13, "[2, 4, 6, 7, 8]", "[2, 3, 4, 6, 9]"],
  [14, "[2, 4, 5, 6, 7]", "[2, 4, 6, 7, 10]"],
  [15, "[2, 3, 4, 6, 11]", "[2, 5, 7, 10, 15]"],
];

const forbidden = [
  ['data-action="quick-show-log" data-log-type="Potty"', "Potty must require a pee or poop outcome before logging."],
  ['upsertRecord("boardingDog"', "Dog Show module must not write boarding dog records."],
  ['saveDogShowRecord("boardingDog"', "Dog Show module must not save boarding dog records."],
  ['upsertRecord("careLog"', "Dog Show module must not write boarding/shared care logs."],
  ['upsertRecord("scheduledCareTask"', "Dog Show prep tasks must stay out of the boarding scheduler."],
];

const failures = [];
if (!fs.existsSync("assets/icons/bis-rosette.png")) failures.push("The Dog Show Home rosette asset is missing.");
if (read("index.html").includes("Run show weekends, dog care, prep timing, helper assignments, and results.")) failures.push("The removed Dog Show workspace description is still rendered.");
if (read("js/dog-show.js").includes("Format pending")) failures.push("Planner cards still expose the unclear Format pending placeholder.");
if (read("js/dog-show.js").includes("Canine Chronicle calendar</span>")) failures.push("The removed Canine Chronicle calendar badge is still rendered.");
for (const [path, needle, message] of required) {
  if (!read(path).includes(needle)) failures.push(message);
}
const dogShowSource = read("js/dog-show.js");
const calendarScraperSource = read("supabase/functions/show-calendar-scrape/index.ts");
const plannerStateField = dogShowSource.match(/<label class="dog-show-field-wide">States[\s\S]*?<\/label>/)?.[0] || "";
if (plannerStateField.includes("required")) failures.push("The Planner States field still blocks nationwide searches.");
if (calendarScraperSource.includes("At least one valid state is required")) failures.push("The calendar importer still rejects nationwide searches.");
if (!dogShowSource.includes('id="dogShowAkcJudgeSearchForm"') || !dogShowSource.includes("DOG_SHOW_AKC_JUDGE_RESULTS_URL")) failures.push("The AKC judge link does not submit the selected judge name to the official directory search.");
if (!dogShowSource.includes('data-action="remove-planned-show"') || !dogShowSource.includes(">Remove Show</button>")) failures.push("Added planner shows do not expose a distinct Remove Show action.");
if (!dogShowSource.includes("function dogShowPlannerConflictsForShow") || !dogShowSource.includes(">Date Conflict</span>")) failures.push("Planner cards do not identify overlapping added or potential shows.");
if (!dogShowSource.includes(">In Potential Plan</span>")) failures.push("Planner cards do not visibly identify potential-plan membership.");
if (!read("styles.css").includes(".dog-show-remove-added-button") || !read("styles.css").includes(".dog-show-planner-state-flags")) failures.push("Planner added, potential, and conflict states are not visually distinct.");
const pointScheduleSource = dogShowSource.slice(dogShowSource.indexOf("const DOG_SHOW_AKC_POINT_SCHEDULES"), dogShowSource.indexOf("const DOG_SHOW_AKC_STATE_NAMES"));
for (const [division, dogs, bitches] of official2026SiberianHuskySchedules) {
  const block = pointScheduleSource.match(new RegExp(`\\n\\s*${division}: \\{[\\s\\S]*?dogs: (\\[[^\\n]+\\]),\\n\\s*bitches: (\\[[^\\n]+\\])`));
  if (!block || block[1] !== dogs || block[2] !== bitches) failures.push(`The 2026 AKC Siberian Husky thresholds for Division ${division} do not match the official schedule.`);
}
const dogEntryFormSource = dogShowSource.slice(dogShowSource.indexOf("function openDogShowEntryForm"), dogShowSource.indexOf("function openDogShowPottyPicker"));
const ringRowsIndex = dogEntryFormSource.indexOf('id="dogShowRingScheduleRows"');
const addRingIndex = dogEntryFormSource.indexOf('data-action="add-ring-schedule"');
if (!(ringRowsIndex >= 0 && ringRowsIndex < addRingIndex)) failures.push("Add Ring Appearance must render after the existing ring appearance rows.");
if (!dogShowSource.includes('expanded ? dogShowTimelineLogsHtml(items, entry, canRemoveLogs) : ""')) failures.push("Collapsed Dog Show timeline dates must not render their logs before expansion.");
const duplicateTaskSource = dogShowSource.slice(dogShowSource.indexOf("function openDuplicateDogShowTask"), dogShowSource.indexOf("async function saveDogShowRecord"));
if (duplicateTaskSource.includes("setMinutes")) failures.push("Duplicate show tasks must not change the original date and time.");
const rosterRowSource = dogShowSource.slice(dogShowSource.indexOf("function dogShowEntryRowHtml"), dogShowSource.indexOf("function dogShowRenderEmpty"));
if (rosterRowSource.includes('entry.dogType === "boardingDog" ? "Boarding" : "Our Dog"')) failures.push("Dog roster quick-view details must not show the irrelevant record origin.");
if (!rosterRowSource.includes('return `<article class="dog-show-dog-row')) failures.push("Dog roster cards must use a non-button container so quick actions remain valid controls.");
const pottyHandlerStart = dogShowSource.lastIndexOf('if (action.dataset.action === "quick-show-potty"');
const pottyHandlerSource = dogShowSource.slice(pottyHandlerStart, dogShowSource.indexOf('if (action.dataset.action === "quick-show-log"', pottyHandlerStart));
if (pottyHandlerSource.includes("openDogShowEntryForm")) failures.push("Potty quick logging must close instead of opening the main dog dialog.");
const noteSaveSource = dogShowSource.slice(dogShowSource.indexOf("async function saveDogShowNote"), dogShowSource.indexOf("async function saveDogShowResult"));
if (noteSaveSource.includes("openDogShowEntryForm")) failures.push("Saving a quick note must close instead of opening the main dog dialog.");
const stylesSource = read("styles.css");
if (stylesSource.includes(".dog-show-dog-row.has-conflict")) failures.push("Dog roster cards must not use the purple dashed conflict outline.");
if (stylesSource.includes("content: attr(data-show-preview)") || dogShowSource.includes("data-show-preview=")) failures.push("Yearly Show Calendar hover must not render the clipped dark preview overlay.");
const rosterCopyStyles = stylesSource.slice(stylesSource.indexOf(".dog-show-dog-copy strong"), stylesSource.indexOf(".dog-show-dog-status"));
if (rosterCopyStyles.includes("text-overflow: ellipsis") || rosterCopyStyles.includes("white-space: nowrap")) failures.push("Dog roster quick-view text must wrap instead of truncating information.");
for (const [needle, message] of forbidden) {
  if (dogShowSource.includes(needle)) failures.push(message);
}

if (failures.length) {
  console.error(failures.map((failure) => `- ${failure}`).join("\n"));
  process.exit(1);
}

console.log("Dog Show static checks passed.");
